#!/usr/bin/env -S node --experimental-strip-types
/**
 * check-prose-anchors.ts — the prose-anchor validity gate
 * (033-PP-PLAN-skill-refiner-sak-amendment-v7 § 14.16, prose-schema-coherence).
 *
 * Kernel schema `$comment` fields cite sections of the 6767-h master spec
 * ("6767-h §3.1"). Those citations are load-bearing prose anchors: if a 6767-h
 * section is renumbered or removed, the citation dangles silently. This gate
 * makes the coherence machine-checked:
 *
 *   1. load the VENDORED heading inventory
 *      (schemas/prose-anchors/6767-h.headings.json — generated by
 *      scripts/parse-spec-headings.ts from the 6767-h source doc);
 *   2. walk every `$comment` string in schemas/ ** / *.json;
 *   3. extract every 6767-h section reference;
 *   4. FAIL on any reference that does not resolve to a real section heading
 *      (a leaf or intermediate node of the 6767-h section tree).
 *
 * Deterministic, offline, no LLM in the loop (§ 14.16.1 stability discipline).
 * Renumbering a 6767-h section requires regenerating the inventory in the same
 * commit as the schema-side citation update.
 *
 * Exit codes:
 *   0 — every cited anchor resolves
 *   1 — at least one dangling anchor (neutral error copy names each one)
 *
 * Usage:
 *   node --experimental-strip-types scripts/check-prose-anchors.ts [--root <dir>]
 *
 * `--root` points the gate at a repo-shaped fixture tree (test harness use).
 */

import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(SCRIPT_DIR, '..');

/** The inventory shape scripts/parse-spec-headings.ts emits (kept standalone — scripts do not cross-import). */
export interface HeadingInventory {
  readonly source: string;
  readonly source_sha256: string;
  readonly headings: readonly {
    readonly level: number;
    readonly text: string;
    readonly line: number;
    readonly numeric_id: string | null;
    readonly anchors: readonly string[];
  }[];
}

/**
 * Slug normalization — MUST mirror `slugify` in scripts/parse-spec-headings.ts
 * (the generator side). The end-to-end named-anchor test in
 * src/__tests__/prose-anchor-validity.test.ts pins the two implementations to
 * the same behavior.
 */
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/** Repo-relative path of the vendored inventory. */
export const INVENTORY_PATH = 'schemas/prose-anchors/6767-h.headings.json';

/**
 * A 6767-h citation inside a `$comment`: the short doc handle ("6767-h §3.1")
 * or the full filename form, then `§` and the section ID — numerical hierarchy
 * ("3.1") or named ("Skill-Frontmatter"). Trailing sentence punctuation is not
 * part of the ID.
 */
const CITATION_PATTERN =
  /\b6767-h(?:-SPEC-DR-STND-claude-code-extensions-master(?:\.md)?)?\s*§\s*([A-Za-z0-9][A-Za-z0-9.-]*)/g;

export interface Citation {
  /** Repo-root-relative schema file path. */
  readonly file: string;
  /** JSON path of the `$comment` carrying the citation. */
  readonly at: string;
  /** The cited section ID, trailing punctuation stripped. */
  readonly anchor: string;
}

/** Extract every 6767-h section reference from one `$comment` string. */
export function extractReferences(comment: string): string[] {
  const refs: string[] = [];
  for (const match of comment.matchAll(CITATION_PATTERN)) {
    const raw = match[1];
    if (raw === undefined) continue;
    const anchor = raw.replace(/[.-]+$/, '');
    if (anchor.length > 0) refs.push(anchor);
  }
  return refs;
}

/** Recursively collect citations from every `$comment` in a parsed JSON value. */
function collectFromValue(value: unknown, file: string, path: string, out: Citation[]): void {
  if (Array.isArray(value)) {
    value.forEach((item, i) => collectFromValue(item, file, `${path}[${i}]`, out));
    return;
  }
  if (value === null || typeof value !== 'object') return;
  for (const [key, child] of Object.entries(value)) {
    const childPath = `${path}/${key}`;
    if (key === '$comment' && typeof child === 'string') {
      for (const anchor of extractReferences(child)) {
        out.push({ file, at: childPath, anchor });
      }
    } else {
      collectFromValue(child, file, childPath, out);
    }
  }
}

/** Every *.json file under a directory (recursive, sorted for determinism). */
function jsonFilesUnder(dir: string): string[] {
  const out: string[] = [];
  if (!existsSync(dir)) return out;
  for (const entry of readdirSync(dir, { withFileTypes: true }).sort((a, b) =>
    a.name.localeCompare(b.name),
  )) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...jsonFilesUnder(full));
    else if (entry.isFile() && entry.name.endsWith('.json')) out.push(full);
  }
  return out;
}

/** Collect every 6767-h citation from `$comment` fields under `<root>/schemas`. */
export function collectCitations(root: string = REPO_ROOT): Citation[] {
  const citations: Citation[] = [];
  const inventoryAbs = join(root, INVENTORY_PATH);
  for (const file of jsonFilesUnder(join(root, 'schemas'))) {
    if (file === inventoryAbs) continue; // the inventory documents the mechanism, not a citation
    const parsed: unknown = JSON.parse(readFileSync(file, 'utf-8'));
    collectFromValue(parsed, relative(root, file), '', citations);
  }
  return citations;
}

/** Load the vendored inventory under `root`. */
export function loadInventory(root: string = REPO_ROOT): HeadingInventory {
  return JSON.parse(readFileSync(join(root, INVENTORY_PATH), 'utf-8')) as HeadingInventory;
}

/**
 * Whether a cited section ID resolves to a heading in the inventory. Numeric
 * IDs ("3.1") match a heading's `numeric_id` exactly; named IDs
 * ("Skill-Frontmatter") slug-match any heading anchor.
 */
export function resolves(anchor: string, inventory: HeadingInventory): boolean {
  if (/^\d+(?:\.\d+)*$/.test(anchor)) {
    return inventory.headings.some((h) => h.numeric_id === anchor);
  }
  const slug = slugify(anchor);
  return inventory.headings.some((h) => h.anchors.includes(slug));
}

/** Every citation under `root` that does NOT resolve against the inventory. */
export function findDanglingAnchors(root: string = REPO_ROOT): {
  citations: Citation[];
  dangling: Citation[];
} {
  const inventory = loadInventory(root);
  const citations = collectCitations(root);
  return { citations, dangling: citations.filter((c) => !resolves(c.anchor, inventory)) };
}

function main(): void {
  // Optional `--root <dir>` override (used by the test harness against fixtures).
  const rootFlag = process.argv.indexOf('--root');
  const root = rootFlag !== -1 ? (process.argv[rootFlag + 1] ?? REPO_ROOT) : REPO_ROOT;

  if (!existsSync(join(root, INVENTORY_PATH))) {
    process.stderr.write(
      `prose-anchors: missing inventory at ${INVENTORY_PATH}. Generate it with ` +
        'pnpm run codegen:prose-anchors -- <path-to-6767-h-spec.md> --out ' +
        `${INVENTORY_PATH}\n`,
    );
    process.exit(1);
  }

  const { citations, dangling } = findDanglingAnchors(root);

  if (dangling.length === 0) {
    process.stdout.write(
      `prose-anchors: OK — ${citations.length} 6767-h citation(s) across schemas/ ` +
        'all resolve to real section headings.\n',
    );
    process.exit(0);
  }

  // Neutral error copy — states the rule and the resolution path.
  process.stderr.write(
    `prose-anchors: ${dangling.length} of ${citations.length} 6767-h citation(s) do not ` +
      'resolve to a section heading in the vendored inventory ' +
      `(${INVENTORY_PATH}). If the 6767-h master spec changed, regenerate the inventory ` +
      'in the same commit (pnpm run codegen:prose-anchors); if a schema $comment cites a ' +
      'renumbered/removed section, update the citation. Dangling anchor(s):\n',
  );
  for (const c of dangling) {
    process.stderr.write(`  ${c.file} ${c.at}: §${c.anchor}\n`);
  }
  process.exit(1);
}

// Run only when invoked as a script (not when imported by the test harness).
if (process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1]) {
  main();
}
